<?php
function page_header(string $title,string $description='Prepaid mobile top-ups for US numbers. Choose your carrier, pick a plan, and track your recharge with MI Tech Wireless.',bool $checkout=false): void {
    $path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH);$name=setting('site_name','MI Tech Wireless');
    $primary=setting('color_primary','#e21e2c');if(!preg_match('/^#[a-f0-9]{6}$/i',$primary))$primary='#e21e2c';
    $secondary=setting('color_secondary','#17191d');if(!preg_match('/^#[a-f0-9]{6}$/i',$secondary))$secondary='#17191d';
    $accent=setting('color_accent','#fff1f2');if(!preg_match('/^#[a-f0-9]{6}$/i',$accent))$accent='#fff1f2';
    // The landing page inlines its small, compressed style bundle to remove two
    // blocking network requests. Other pages share the cacheable asset files.
    $styles=$path==='/'?'<style>'.file_get_contents(ROOT.'/assets/tailwind.css').file_get_contents(ROOT.'/assets/site.css').'</style>':'<link rel="stylesheet" href="'.asset('tailwind.css').'"><link rel="stylesheet" href="'.asset('site.css').'">';
    ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> · <?=e($name)?></title><meta name="description" content="<?=e($description)?>"><meta name="theme-color" content="<?=$primary?>"><link rel="icon" href="/assets/brand/favicon-32.png" sizes="32x32"><link rel="apple-touch-icon" href="/assets/brand/apple-touch-icon.png"><?=$styles?><script src="<?=asset('site.min.js')?>" defer></script><?php if($checkout&&checkout_ready()):?><script src="https://js.stripe.com/v3/" defer></script><script src="<?=asset('checkout.min.js')?>" defer></script><?php endif;?></head><body style="--primary:<?=$primary?>;--secondary:<?=$secondary?>;--accent:<?=$accent?>">
<a class="skip-link" href="#main">Skip to content</a><div class="announcement"><div class="container"><span><?=icon('globe')?> US prepaid top-ups. A little easier.</span><span class="announcement-right">USD $ <span class="flag" aria-label="United States">🇺🇸</span></span></div></div>
<header class="site-header"><div class="container nav-shell"><a class="brand" href="/" aria-label="<?=e($name)?> home"><img src="<?=e(setting('site_logo','/assets/brand/logo.svg'))?>" width="176" height="81" alt="<?=e($name)?>"></a><button class="menu-toggle" type="button" aria-label="Open navigation" aria-controls="main-nav" aria-expanded="false"><?=icon('menu')?></button><nav id="main-nav" aria-label="Main navigation"><a class="<?=$path==='/'?'active':''?>" href="/">Home</a><a class="<?=str_starts_with($path,'/carriers')?'active':''?>" href="/carriers">Carriers</a><a href="/#how-it-works">How it works</a><a class="<?=$path==='/faq'?'active':''?>" href="/faq">Help & FAQs</a><a class="nav-track" href="/track"><?=icon('bag')?> Track order</a></nav></div></header>
<main id="main">
<?php if(isset($_SESSION['flash'])):?><div class="container"><div class="notice success" role="status"><?=e($_SESSION['flash'])?></div></div><?php unset($_SESSION['flash']);endif;
}
function page_footer(): void { ?>
</main><footer class="site-footer"><div class="container footer-grid"><div class="footer-brand"><a href="/"><img src="/assets/brand/logo-light.svg" width="170" height="85" alt="MI Tech Wireless" loading="lazy"></a><p>Keeping you connected.<br>One recharge at a time.</p><a class="support-email" href="mailto:<?=e(setting('support_email','info@mitechwireless.com'))?>"><?=e(setting('support_email','info@mitechwireless.com'))?></a></div><div><h2>Explore</h2><a href="/carriers">All carriers</a><a href="/track">Track your order</a><a href="/about">About us</a></div><div><h2>Here to help</h2><a href="/faq">Help & FAQs</a><a href="/contact">Contact us</a><a href="/refund-policy">Refund policy</a></div><div><h2>The details</h2><a href="/terms">Terms of service</a><a href="/privacy">Privacy policy</a><?php foreach(json_decode(setting('footer_links','[]'),true)?:[] as $link):?><a href="<?=e($link['url'])?>"><?=e($link['label'])?></a><?php endforeach;?><div class="payment-labels"><span>VISA</span><span>Mastercard</span><span>AMEX</span></div><small><?=request_checkout_enabled()?'One-time prepaid top-ups':'Secure card payments through Stripe'?></small></div></div><div class="container footer-bottom"><span>© <?=date('Y')?> <?=e(setting('site_name','MI Tech Wireless'))?>. All rights reserved.</span><span>United States · English · USD $</span></div><div class="container trademark-note">Carrier names are trademarks of their respective owners. MI Tech Wireless is an independent service; carrier availability and plan eligibility must be confirmed before purchase.</div></footer></body></html>
<?php }
function page_intro(string $eyebrow,string $title,string $text): void {echo '<section class="page-intro container"><p class="eyebrow">'.e($eyebrow).'</p><h1>'.e($title).'</h1><p class="lead">'.e($text).'</p></section>';}
function faq_list(array $items): void {foreach($items as $i=>$faq){echo '<details class="faq-row"><summary>'.e($faq['question']).'<span aria-hidden="true">+</span></summary><p>'.nl2br(e($faq['answer'])).'</p></details>';}}
function order_details(array $o): void {?>
<dl class="order-details"><?php foreach(['Order ID'=>$o['order_number'],'Mobile number'=>format_phone($o['recharge_phone']),'Carrier'=>$o['carrier_name'],'Plan'=>$o['plan_name'],'Total'=>money($o['amount_cents']),'Placed'=>when($o['created_at'])] as $key=>$value):?><div><dt><?=e($key)?></dt><dd><?=e($value)?></dd></div><?php endforeach;?></dl>
<div class="order-states"><div><span>Payment</span><?=status_badge($o['payment_status'])?></div><div><span>Recharge</span><?=status_badge($o['recharge_status'])?></div></div>
<?php }
